# solution.py

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    graph = [[] for _ in range(n+1)]

    for i in range(m):
        u, v, w = map(int, lines[2+i].split())
        edges.append((u, v, w, i+1))
        graph[u].append((v, i))
        graph[v].append((u, i))

    def bfs(start, end, exclude_edges):
        if start == end:
            return True
        visited = [False] * (n+1)
        queue = [start]
        visited[start] = True
        while queue:
            u = queue.pop(0)
            for v, idx in graph[u]:
                if idx in exclude_edges:
                    continue
                if not visited[v]:
                    visited[v] = True
                    if v == end:
                        return True
                    queue.append(v)
        return False

    def get_all_path_edges():
        all_edges = set()
        def dfs(u, target, visited, path):
            nonlocal all_edges
            if u == target:
                for e in path:
                    all_edges.add(e)
                return True
            visited.add(u)
            for v, idx in graph[u]:
                if v not in visited:
                    if dfs(v, target, visited, path + [idx]):
                        return True
            visited.remove(u)
            return False
        dfs(s, t, set(), [])
        return all_edges

    if not bfs(s, t, set()):
        return "0\n0\n"

    min_cost = float('inf')
    best_1_edge = None
    best_2_edges = None

    for i in range(m):
        exclude = {i}
        if not bfs(s, t, exclude):
            cost = edges[i][2]
            if cost < min_cost:
                min_cost = cost
                best_1_edge = i

    pb = best_1_edge
    if pb is not None:
        min_cost = edges[pb][2]
        best_2_edges = (pb, None)

    path_edges = get_all_path_edges()
    edge_indices = sorted(list(path_edges))

    if best_1_edge is not None:
        result = f"{min_cost}\n1\n{best_1_edge+1}"
        return result

    for i in range(len(edge_indices)):
        for j in range(i+1, len(edge_indices)):
            a, b = edge_indices[i], edge_indices[j]
            exclude = {a, b}
            if not bfs(s, t, exclude):
                cost_a = edges[a][2]
                cost_b = edges[b][2]
                cost = cost_a + cost_b
                if cost < min_cost:
                    min_cost = cost
                    best_2_edges = (a, b)

    if best_2_edges is not None:
        a, b = best_2_edges
        indices = sorted([a + 1, b + 1])
        return f"{min_cost}\n2\n{' '.join(map(str, indices))}"

    return "-1"
