import math

def get_divisors(n):
    """Get all divisors of n greater than 1"""
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return sorted([d for d in divs if d > 1], reverse=True)

def gcd(a, b):
    return math.gcd(a, b)

def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        n = int(lines[i])

        all_divs = get_divisors(n)

        # Calculate moves needed for sorted arrangement (checking coprime pairs)
        moves = 0
        if len(all_divs) > 0:
            for i in range(len(all_divs)):
                next_idx = (i + 1) % len(all_divs)
                if gcd(all_divs[i], all_divs[next_idx]) == 1:
                    moves += 1

        # Build output string
        result = " ".join(map(str, all_divs)) + "\n" + str(moves) + "\n"
        results.append(result)

    return "".join(results)
