def tokenize(s):
    """Split string into tokens"""
    tokens = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
        elif s[i] in '+-()':
            tokens.append(s[i])
            i += 1
        else:
            i += 1
    return tokens

