    stack = []
    in_stack = [False] * (n + 1)
    scc_nodes = defaultdict(list)

    def tarjan(u):
        nonlocal timer, scc_count
        disc[u] = low[u] = timer
        timer += 1
        stack.append(u)
        in_stack[u] = True

        for v, _ in graph[u]:
            if v == u:
                continue  # skip self-loops for now
            if not disc[v]:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif in_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            scc_nodes[scc_count].append(u)
            while stack:
                w = stack.pop()
                in_stack[w] = False
                scc_nodes[scc_count].append(w)
            scc_count += 1

    # First pass to mark nodes and build SCCs
    for i in range(1, n + 1):
        if not disc[i] and i in graph or not disc[i]:
            # Only run if node has outgoing edges or we still need to process
            if not disc[i]:
                tarjan(i)

    # Identify which nodes are part of non-trivial SCCs (size > 1 or has self-loop)
    has_cycle = [False] * (n + 1)

    for scc in scc_nodes.values():
        if len(scc) > 1:
            for u in scc:
