    # Also check self-loops
    for u in range(1, n + 1):
        for v, w in graph[u]:
            if v == u:
                has_cycle[u] = True

    # For queries where starting node has a cycle, answer is always YES for any s_i, t_i
    # Because we can drive cycles with various lengths

    results = []
    for v_idx, l_idx in enumerate(range(0, q)):
        start_node, s_i, t_i = queries[l_idx]

