Looking at this problem, I need to determine for each road whether it should be placed inside or outside the ring such that no two roads intersect. This is essentially a 2-SAT problem where:

1. Two roads that cross inside the ring must be on different sides (one inside, one outside)
2. If two roads don't cross, they can be on either side

The key insight is that two chords (a,b) and (c,d) cross inside the circle if their endpoints appear in alternating order around the ring.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        edges.append((a, b))

    def in_arc(x, start, end):
        """Check if x is between start and end going clockwise"""
        if start <= end:
            return start < x < end
        else:
            return x > start or x < end

    def crosses(i, j):
        """Check if edges i and j cross when both are drawn inside the ring"""
        a, b = edges[i]
        c, d = edges[j]

        # If edges share an endpoint, they don't cross
        if a == c or a == d or b == c or b == d:
            return False

        # Check if c and d are in different components when split by a and b
        c_in = in_arc(c, a, b)
        d_in = in_arc(d, a, b)

        return (c_in and not d_in) or (not c_in and d_in)

    # Build 2-SAT problem
    # Variable i: 2*i = inside (i=True), 2*i+1 = outside (i=False)
    num_vars = m
    num_nodes = 2 * num_vars
    adj = [[] for _ in range(num_nodes)]

    for i in range(num_vars):
        for j in range(i + 1, num_vars):
            if crosses(i, j):
                # Crossing edges must be on different sides
                # i inside => j outside: 2*i => 2*j+1
                # i outside => j inside: 2*i+1 => 2*j
                adj[2*i].append(2*j + 1)
                adj[2*i + 1].append(2*j)
                adj[2*j].append(2*i + 1)
                adj[2*j + 1].append(2*i)

    # Find SCCs using Kosaraju's algorithm
    visited = [False] * num_nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    visited = [False] * num_nodes
    comp = [-1] * num_nodes
    comp_id = 0

    def dfs2(u):
        visited[u] = True
        comp[u] = comp_id
        for v in adj[u]:
            if not visited[v]:
                dfs2(v)

    for i in reversed(order):
        if not visited[i]:
            dfs2(i)
            comp_id += 1

    # Check for contradiction (variable and its negation in same SCC)
    for i in range(num_vars):
        if comp[2*i] == comp[2*i + 1]:
            return "Impossible"

    # Assign truth values based on topological order
    ans = [''] * m
    for i in range(m):
        if comp[2*i] > comp[2*i + 1]:
            ans[i] = 'i'
        else:
            ans[i] = 'o'

    return ''.join(ans)
