        for length in range(1, len(s) + 1):
            pc.add(s[:length])
        phone_prefixes.append(pc)

    # Greedily select k prefixes with best marginal benefit
    for _ in range(k):
        if not remaining:
            break

        best_prefix = None
        best_improvement = -float('inf')
        best_idx = -1

        for i, p in enumerate(remaining):
