                        new_len = pl

                if orig_len > 0 and orig_len > new_len:
                    improvement += m
                elif len(p) > orig_len:
                    improvement += m * len(p) - m * orig_len if orig_len > 0 else m * len(p)

            # Track improvement properly
            if improvement > best_improvement:
                best_improvement = improvement
                best_prefix = p
                best_idx = i

